<?php
function mail_settings(PDO $pdo){ $row=$pdo->query("SELECT * FROM email_settings WHERE id=1")->fetch(PDO::FETCH_ASSOC); if(!$row){ $row=['mail_to'=>'powiadomienia@smartmeble.pl','mail_from'=>'powiadomienia@smartmeble.pl']; } return $row; }
function render_template($h,$v){ foreach($v as $k=>$val){ $h=str_replace('{{'.$k.'}}',$val,$h);} return $h; }
function send_html_mail($to,$from,$sub,$html){ return smtp_send($to, $from, envv('SMTP_FROM_NAME','Smart Meble'), $sub, $html); }   // SMTP – config.php
function send_order_email(PDO $pdo,$orderId,$type){ $tpl=file_get_contents(__DIR__.'/mail_template.html'); $s=$pdo->prepare("SELECT o.*, CONCAT(o.client_first_name,' ',o.client_last_name) client_name, s.name status_name FROM orders o LEFT JOIN order_statuses s ON s.id=o.status_id WHERE o.id=?"); $s->execute([$orderId]); $o=$s->fetch(PDO::FETCH_ASSOC); if(!$o) return false; if($type==='new'){ $title="Nowe zamówienie: ".trim($o['client_name']); $content="<h2>Nowe zamówienie</h2><div>Klient: <b>".htmlspecialchars($o['client_name'])."</b></div><div>Przedmiot: ".nl2br(htmlspecialchars($o['item_description']))."</div><div>Data montażu: ".htmlspecialchars($o['install_date'])."</div><div>Status: ".htmlspecialchars($o['status_name'])."</div>"; } elseif($type==='status'){ $title="Zmieniono status zamówienia #".$orderId; $content="<h2>Zmiana statusu</h2><div>Klient: <b>".htmlspecialchars($o['client_name'])."</b></div><div>Nowy status: ".htmlspecialchars($o['status_name'])."</div>"; } else { $title="Aktualizacja zamówienia #".$orderId; $content="<h2>Aktualizacja</h2>"; } $url="https://panel.smartmeble.pl/frontend/order_detail.html?id=".$orderId; $html=render_template($tpl,['content_html'=>$content,'cta_url'=>$url]); $cfg=mail_settings($pdo); $to=$cfg['mail_to']?:'powiadomienia@smartmeble.pl'; $from=$cfg['mail_from']?:'powiadomienia@smartmeble.pl'; return send_html_mail($to,$from,"[Smart Meble] ".$title,$html); }